const ROLE_RANK: Record<AuthRole, number> = { user: 0, staff: 1, admin: 2 };
function roleRank(role: AuthRole): number { return ROLE_RANK[role]; }
function isDowngrade(oldRole: AuthRole, newRole: AuthRole): boolean { return roleRank(newRole) < roleRank(oldRole); }

